using Myra.Graphics2D.UI;

namespace OpenGothic.UI
{
	public partial class Hud
	{
		private const int ScreenEdge = 8;

		private readonly DebugOverlay _debugOverlay;
		private readonly Controls _controls;

		public Hud()
		{
			BuildUI();

			// Panel defaults to Left/Top, which would size it to its content. Stretching it
			// makes it fill the desktop so children can anchor to opposite corners.
			HorizontalAlignment = HorizontalAlignment.Stretch;
			VerticalAlignment = VerticalAlignment.Stretch;

			_debugOverlay = new DebugOverlay
			{
				HorizontalAlignment = HorizontalAlignment.Left,
				VerticalAlignment = VerticalAlignment.Top,
				Left = ScreenEdge,
				Top = ScreenEdge
			};

			_controls = new Controls
			{
				HorizontalAlignment = HorizontalAlignment.Right,
				VerticalAlignment = VerticalAlignment.Bottom,
				Left = -ScreenEdge,
				Top = -ScreenEdge
			};

			Widgets.Add(_debugOverlay);
			Widgets.Add(_controls);
		}

		/// <summary>The toggleable stats block. The controls block stays visible.</summary>
		public DebugOverlay DebugOverlay => _debugOverlay;

		public void ToggleDebugOverlay()
		{
			_debugOverlay.Visible = !_debugOverlay.Visible;
		}
	}
}
